package com.tradingplatform.decision;
import com.tradingplatform.market.*; import com.tradingplatform.signal.*; import java.math.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class DecisionEngine { private final IndicatorEngine indicators; private final SignalEngine signals; private final int minimumScore; private final BigDecimal minimumRr,riskPercent;
 public DecisionEngine(IndicatorEngine i,SignalEngine s,@Value("${trading.decision.minimum-score:70}")int min,@Value("${trading.decision.minimum-risk-reward:1.5}")BigDecimal rr,@Value("${trading.decision.risk-per-trade-percent:1}")BigDecimal risk){indicators=i;signals=s;minimumScore=min;minimumRr=rr;riskPercent=risk;}
 public Decision evaluate(String symbol,Timeframe timeframe,List<Candle> candles,BigDecimal capital){IndicatorSnapshot i=indicators.calculate(candles);MarketContext c=new MarketContext(symbol,timeframe,candles,i);SignalResult technical=signals.evaluate(c);MarketRegime regime=regime(c);int score=score(technical,regime,c);boolean tradable=(technical.signal()==Signal.BUY||technical.signal()==Signal.SELL)&&score>=minimumScore&&technical.riskReward()!=null&&technical.riskReward().compareTo(minimumRr)>=0&&regime!=MarketRegime.HIGH_VOLATILITY;Signal direction=tradable?technical.signal():Signal.HOLD;BigDecimal entry=technical.entry(),stop=technical.stopLoss(),risk=entry==null||stop==null?BigDecimal.ZERO:entry.subtract(stop).abs();BigDecimal target1=direction==Signal.HOLD?null:technical.target();BigDecimal target2=target1==null||entry==null?null:(direction==Signal.BUY?entry.add(risk.multiply(BigDecimal.valueOf(3))):entry.subtract(risk.multiply(BigDecimal.valueOf(3))));BigDecimal allowed=capital.multiply(riskPercent).divide(BigDecimal.valueOf(100),6,RoundingMode.HALF_UP);int qty=risk.signum()>0?allowed.divide(risk,0,RoundingMode.DOWN).intValue():0;BigDecimal required=entry==null?BigDecimal.ZERO:entry.multiply(BigDecimal.valueOf(qty));List<String> reasons=new ArrayList<>(technical.reasons());List<String> risks=new ArrayList<>();if(direction==Signal.HOLD)risks.add("NO TRADE: score, confirmation, regime, or risk/reward threshold was not met.");if(regime==MarketRegime.HIGH_VOLATILITY)risks.add("Volatility is elevated; setup is filtered.");if(qty<1)risks.add("Capital is insufficient for the configured risk per trade.");return new Decision(UUID.randomUUID(),symbol,direction,Instant.now(),score,quality(score),BigDecimal.valueOf(score).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP),entry,entry==null?null:entry.subtract(i.atr14().multiply(BigDecimal.valueOf(.15))),entry==null?null:entry.add(i.atr14().multiply(BigDecimal.valueOf(.15))),stop,target1,target2,technical.riskReward(),qty,required,regime,direction==Signal.HOLD?"Wait for confirmed multi-factor alignment.":"Market entry only while price remains inside the entry range.",stop==null?"Insufficient analysis data.":"Exit when price crosses stop loss.",List.copyOf(reasons),List.copyOf(risks));}
 private int score(SignalResult s,MarketRegime r,MarketContext c){int score=s.signalStrength();if(r==MarketRegime.TRENDING_BULL&&s.signal()==Signal.BUY||r==MarketRegime.TRENDING_BEAR&&s.signal()==Signal.SELL)score+=5;if(c.candles().get(c.candles().size()-1).volume().compareTo(c.indicators().volumeSma())>0)score+=5;return Math.min(100,score);} private MarketRegime regime(MarketContext c){BigDecimal p=c.price(),atrPct=c.indicators().atr14().divide(p,6,RoundingMode.HALF_UP);if(atrPct.compareTo(BigDecimal.valueOf(.04))>0)return MarketRegime.HIGH_VOLATILITY;if(atrPct.compareTo(BigDecimal.valueOf(.003))<0)return MarketRegime.LOW_VOLATILITY;if(p.compareTo(c.indicators().ema50())>0&&(c.indicators().ema200()==null||c.indicators().ema50().compareTo(c.indicators().ema200())>0))return MarketRegime.TRENDING_BULL;if(p.compareTo(c.indicators().ema50())<0&&(c.indicators().ema200()==null||c.indicators().ema50().compareTo(c.indicators().ema200())<0))return MarketRegime.TRENDING_BEAR;return MarketRegime.RANGE_BOUND;} private String quality(int score){return score>=80?"A+":score>=70?"A":score>=60?"B":score>=50?"C":"NO_TRADE";} }
